//! Shared helpers for comparing waveforms against LALSimulation reference data.
//!
//! The reference data are generated by `scripts/generate_reference_data.py`.
#![allow(dead_code)]

use num_complex::Complex;
use serde::Deserialize;

pub type C64 = Complex<f64>;

#[derive(Debug, Deserialize)]
pub struct ReferenceFile {
    pub lalsimulation_version: String,
    pub cases: Vec<Case>,
}

#[derive(Debug, Deserialize, Clone)]
pub struct Case {
    pub approximant: String,
    pub mass_1: f64,
    pub mass_2: f64,
    pub spin_1: [f64; 3],
    pub spin_2: [f64; 3],
    pub luminosity_distance: f64,
    pub inclination: f64,
    pub phi_ref: f64,
    pub f_min: f64,
    pub f_ref: f64,
    pub f_max: f64,
    pub frequencies: Vec<f64>,
    pub hplus_real: Vec<f64>,
    pub hplus_imag: Vec<f64>,
    pub hcross_real: Vec<f64>,
    pub hcross_imag: Vec<f64>,
    /// Waveform flags inserted in the LALDict (e.g. `PhenomXPrecVersion`).
    #[serde(default)]
    pub lal_flags: std::collections::HashMap<String, f64>,
    /// LAL's mode array `(l, m)`, empty for the default modes.
    #[serde(default)]
    pub mode_array: Vec<(u32, i32)>,
}

impl Case {
    pub fn total_mass(&self) -> f64 {
        self.mass_1 + self.mass_2
    }

    /// Mass ratio in the `waveformrs` convention, q = m2 / m1 <= 1.
    pub fn mass_ratio(&self) -> f64 {
        self.mass_2 / self.mass_1
    }

    pub fn hplus(&self) -> Vec<C64> {
        zip_complex(&self.hplus_real, &self.hplus_imag)
    }

    pub fn hcross(&self) -> Vec<C64> {
        zip_complex(&self.hcross_real, &self.hcross_imag)
    }

    pub fn label(&self) -> String {
        format!(
            "{} m1={} m2={} s1={:?} s2={:?} iota={} phi={} fref={}",
            self.approximant,
            self.mass_1,
            self.mass_2,
            self.spin_1,
            self.spin_2,
            self.inclination,
            self.phi_ref,
            self.f_ref
        )
    }
}

fn zip_complex(re: &[f64], im: &[f64]) -> Vec<C64> {
    re.iter().zip(im).map(|(&r, &i)| C64::new(r, i)).collect()
}

/// The reference data `<name>.json`: from the directory in
/// `WAVEFORMRS_REFERENCE_DATA` if set (data generated with the lalsimulation
/// of this machine, e.g. by `scripts/linux/reference.sh`), else from the
/// committed `tests/data` (the conda-forge osx-arm64 build of lalsimulation).
pub fn data_path(name: &str) -> std::path::PathBuf {
    let dir = std::env::var_os("WAVEFORMRS_REFERENCE_DATA")
        .map(std::path::PathBuf::from)
        .unwrap_or_else(|| std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/data"));
    dir.join(format!("{name}.json"))
}

/// Whether this crate mirrors the reference build of lalsimulation
/// operation by operation: on macOS arm64 it reproduces the conda-forge
/// osx-arm64 build (clang's fused multiply-adds, Apple's libm) to rounding,
/// mostly bit for bit.
///
/// Elsewhere the arithmetic differs in the last bits. Against the committed
/// data the libm differs (glibc's `sin`, `pow`, `cbrt`, ... are not Apple's)
/// and so do the fused multiply-adds on x86-64. Against data from this
/// machine's lalsimulation (`WAVEFORMRS_REFERENCE_DATA`), LAL is compiled
/// by GCC, which on aarch64 also fuses products and sums in different
/// statements (on x86-64 a few untraced last-bit differences remain). The
/// ill-conditioned parts of the models turn that into much
/// larger differences, in LAL itself as much as here (docs/linux.md): the
/// IMRPhenomXHM (3,2) mode (relative ~2e-3 between LAL's own Linux and
/// macOS builds) and, through it, every IMRPhenomXHM/XPHM polarisation and
/// the l = 3 modes of IMRPhenomXPHM, and the MSA angles.
pub fn mirrored_build() -> bool {
    cfg!(all(target_os = "macos", target_arch = "aarch64"))
}

/// Tolerances `(relative error, mismatch)` of the suites that need looser
/// ones where [`mirrored_build`] is false, about ten times the largest
/// differences seen between this crate on Linux (arm64 and amd64) and either
/// the osx-arm64 or the Linux lalsimulation, which are themselves of the
/// size of the differences between lalsimulation's own builds
/// (report/data/linux_reference_comparison.json).
const CROSS_BUILD_TOLERANCES: [(&str, (f64, f64)); 14] = [
    ("imrphenomxhm", (1e-3, 1e-6)),
    // the (3,+-2) modes, and the others (up to 2e-9 at mass ratio 30)
    ("imrphenomxhm_modes_32", (2e-2, 4e-5)),
    ("imrphenomxhm_modes", (2e-8, 1e-12)),
    // the l = 3 modes of IMRPhenomXHM and XPHM (tests/modes.rs)
    ("choose_fd_modes_l3", (2e-2, 4e-5)),
    ("choose_fd_modes", (1e-8, 1e-12)),
    ("imrphenomxphm_spintaylor", (1e-3, 1e-6)),
    ("imrphenomxphm_nnlo", (1e-3, 1e-6)),
    ("imrphenomxphm_msa", (1e-3, 1e-6)),
    ("imrphenomxphm_uniform", (1e-3, 1e-6)),
    ("imrphenomxphm_modes", (1e-3, 1e-6)),
    ("imrphenomxphm_spintaylor_fallback", (1e-3, 1e-6)),
    ("imrphenomxp_msa", (1e-7, 1e-12)),
    // absolute difference of the Euler angles
    ("imrphenomxp_spintaylor_angles", (1e-9, 0.0)),
    // spin components and the like, relative to their largest value
    ("spintaylor", (1e-6, 0.0)),
];

/// The tolerances of `suite`: `strict` where [`mirrored_build`] (or where
/// the suite needs nothing looser), else those of
/// [`CROSS_BUILD_TOLERANCES`].
pub fn tolerances(suite: &str, strict: (f64, f64)) -> (f64, f64) {
    if mirrored_build() {
        return strict;
    }
    match CROSS_BUILD_TOLERANCES
        .iter()
        .find(|(name, _)| *name == suite)
    {
        Some(&(_, loose)) => {
            println!(
                "{suite}: not the osx-arm64 build that this crate mirrors, tolerances \
                 {loose:?} instead of {strict:?} (docs/linux.md)"
            );
            loose
        }
        None => strict,
    }
}

pub fn load(name: &str) -> ReferenceFile {
    let path = data_path(name);
    let contents =
        std::fs::read_to_string(&path).unwrap_or_else(|e| panic!("{}: {e}", path.display()));
    serde_json::from_str(&contents).unwrap()
}

/// Trapezoid-like weights for a non-uniform frequency grid.
fn weights(frequencies: &[f64]) -> Vec<f64> {
    let n = frequencies.len();
    (0..n)
        .map(|i| {
            let lo = frequencies[i.saturating_sub(1)];
            let hi = frequencies[(i + 1).min(n - 1)];
            0.5 * (hi - lo)
        })
        .collect()
}

#[derive(Debug, Clone, Copy)]
pub struct Comparison {
    /// max_i |a_i - b_i| / max_i |b_i|
    pub max_relative_error: f64,
    /// 1 - Re<a, b> / sqrt(<a, a><b, b>) with a white noise spectrum,
    /// no maximization over time or phase.
    pub mismatch: f64,
}

pub fn compare(frequencies: &[f64], test: &[C64], reference: &[C64]) -> Comparison {
    assert_eq!(test.len(), reference.len());
    let w = weights(frequencies);
    let mut ab = 0.0;
    let mut aa = 0.0;
    let mut bb = 0.0;
    let mut max_diff: f64 = 0.0;
    let mut max_ref: f64 = 0.0;
    for ((a, b), w) in test.iter().zip(reference).zip(&w) {
        ab += w * (a * b.conj()).re;
        aa += w * a.norm_sqr();
        bb += w * b.norm_sqr();
        max_diff = max_diff.max((a - b).norm());
        max_ref = max_ref.max(b.norm());
    }
    let mismatch = if aa == 0.0 && bb == 0.0 {
        0.0
    } else {
        1.0 - ab / (aa * bb).sqrt()
    };
    Comparison {
        max_relative_error: if max_ref > 0.0 {
            max_diff / max_ref
        } else {
            max_diff
        },
        mismatch,
    }
}

/// Compare both polarizations of every case and panic with a summary if any
/// exceeds the tolerances (those given, or those of [`tolerances`] where the
/// crate does not mirror the reference build).
pub fn check_all<F>(name: &str, max_relative_error: f64, max_mismatch: f64, generate: F)
where
    F: Fn(&Case) -> (Vec<C64>, Vec<C64>),
{
    let (max_relative_error, max_mismatch) = tolerances(name, (max_relative_error, max_mismatch));
    let reference = load(name);
    let mut failures = Vec::new();
    for case in &reference.cases {
        let (hp, hc) = generate(case);
        for (pol, test, truth) in [("plus", hp, case.hplus()), ("cross", hc, case.hcross())] {
            let result = compare(&case.frequencies, &test, &truth);
            println!(
                "{pol:>5}: max rel err {:.3e}, mismatch {:.3e} | {}",
                result.max_relative_error,
                result.mismatch,
                case.label()
            );
            if !(result.max_relative_error <= max_relative_error && result.mismatch <= max_mismatch)
            {
                failures.push(format!("{pol} {:?} {}", result, case.label()));
            }
        }
    }
    assert!(
        failures.is_empty(),
        "{} comparisons failed (tolerances: rel {max_relative_error:e}, mismatch {max_mismatch:e}) against lalsimulation {}:\n{}",
        failures.len(),
        reference.lalsimulation_version,
        failures.join("\n")
    );
}
